(function(root){'use strict';
 const defaults={width:6636,height:3792,citySpan:.82,crossingHours:5,carHours:1,footHours:3.5,scaleFactor:1,origin:{x:.1,y:.12},routingConfirmed:false};
 function config(value={}){const c={...defaults,...value,origin:{...defaults.origin,...value.origin}};for(const [k,min,max] of [['width',1,20000],['height',1,20000],['citySpan',.1,1],['crossingHours',1,20],['carHours',.1,10],['footHours',1,20],['scaleFactor',.2,3]])if(!Number.isFinite(c[k])||c[k]<min||c[k]>max)throw Error('Некорректный масштаб: '+k);if(typeof c.routingConfirmed!=='boolean'||!point(c.origin))throw Error('Некорректная конфигурация сетки');return c;}
 const point=p=>!!p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1;
 const radius=c=>c.width*c.citySpan/(c.crossingHours/c.carHours*Math.sqrt(3))*c.scaleFactor;
 function fractional(p,value){const c=config(value),r=radius(c),x=(p.x-c.origin.x)*c.width,y=(p.y-c.origin.y)*c.height;return {q:(Math.sqrt(3)/3*x-y/3)/r,r:2*y/(3*r)};}
 function hex(p,c){if(!point(p))throw Error('Точка находится за пределами карты');const f=fractional(p,c);let x=Math.round(f.q),z=Math.round(f.r),y=Math.round(-f.q-f.r);const dx=Math.abs(x-f.q),dz=Math.abs(z-f.r),dy=Math.abs(y+f.q+f.r);if(dx>dy&&dx>dz)x=-y-z;else if(dz>dy)z=-x-y;return {q:x||0,r:z||0};}
 function center(h,value){const c=config(value),r=radius(c);return {x:c.origin.x+r*Math.sqrt(3)*(h.q+h.r/2)/c.width,y:c.origin.y+r*1.5*h.r/c.height};}
 const distance=(a,b)=>Math.max(Math.abs(a.q-b.q),Math.abs(a.r-b.r),Math.abs(a.q+a.r-b.q-b.r));
 const key=h=>h.q+','+h.r;
 function cells(value){const c=config(value),out=[];for(let q=-40;q<=40;q++)for(let r=-40;r<=40;r++){const p=center({q,r},c);if(p.x<-.2||p.x>1.2||p.y<-.25||p.y>1.25)continue;const size=radius(c),corners=Array.from({length:6},(_,i)=>{const a=(60*i-30)*Math.PI/180;return {x:p.x+size*Math.cos(a)/c.width,y:p.y+size*Math.sin(a)/c.height};});out.push({q,r,center:p,corners});}return out;}
 function edge(e){if(!e||!['aq','ar','bq','br'].every(k=>Number.isInteger(e[k])&&Math.abs(e[k])<=100)||distance({q:e.aq,r:e.ar},{q:e.bq,r:e.br})!==1||typeof e.car!=='boolean'||typeof e.foot!=='boolean'||!Number.isFinite(e.cost)||e.cost<1||e.cost>20)throw Error('Переход должен соединять соседние гексы; стоимость от 1 до 20');return e;}
 function path(a,b,edges,mode){const start=key(a),end=key(b);if(start===end)return null;const graph=new Map();for(const raw of edges){const e=edge(raw);if(!e[mode]||e.blocked)continue;const x=key({q:e.aq,r:e.ar}),y=key({q:e.bq,r:e.br});if(!graph.has(x))graph.set(x,[]);if(!graph.has(y))graph.set(y,[]);graph.get(x).push([y,e.cost]);graph.get(y).push([x,e.cost]);}const costs=new Map([[start,0]]),previous=new Map(),open=new Set([start]);while(open.size){let u=[...open].sort((x,y)=>costs.get(x)-costs.get(y))[0];open.delete(u);if(u===end){const route=[];for(let v=end;v;v=previous.get(v)){const [q,r]=v.split(',').map(Number);route.unshift({q,r});}return {steps:costs.get(end),cells:route};}for(const [v,w] of graph.get(u)||[]){const cost=costs.get(u)+w;if(cost<(costs.get(v)??Infinity)){costs.set(v,cost);previous.set(v,u);open.add(v);}}}return null;}
 function route(from,to,edges,value){if(!point(from)||!point(to))throw Error('Не заданы начальная точка или назначение');const c=config(value),a=hex(from,c),b=hex(to,c),estimate=distance(fractional(from,c),fractional(to,c));const car=c.routingConfirmed?path(a,b,edges,'car'):null,foot=c.routingConfirmed?path(a,b,edges,'foot'):null;return {estimate,preliminary:!car||!foot,car:car?{...car,hours:Math.round(car.steps*c.carHours*4)/4}:null,foot:foot?{...foot,hours:Math.round(foot.steps*c.footHours*4)/4}:null,estimatedCar:Math.round(estimate*c.carHours*4)/4,estimatedFoot:Math.round(estimate*c.footHours*4)/4};}
 const api={defaults,config,point,radius,fractional,hex,center,distance,cells,edge,path,route,key};root.ND_MAP_ROUTING=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
